# On an entity with a Nav Agent. World positions on the baked NavMesh.
POINTS = [(6, 0, -6), (6, 0, 6), (-6, 0, 6)]

class Patrol(horizon.Behavior):
    def on_start(self):
        self.i = -1
        self.go_next()

    def go_next(self):
        self.i = (self.i + 1) % len(POINTS)
        if not horizon.nav.moveTo(self.entity_id, *POINTS[self.i]):
            horizon.log(f"patrol point {self.i} is not reachable")

    def on_update(self, dt):
        # isMoving turns false on arrival (and after a refusal).
        if not horizon.nav.isMoving(self.entity_id):
            self.go_next()

import horizon

class Inventory(horizon.Behavior):
    open = False

    # "Inventory" is a button action. While the inventory is open the cursor
    # is visible and clicks go to the UI; the game still reads the keys.
    def on_input_pressed(self, name):
        if name != "Inventory":
            return
        self.open = not self.open
        if self.open:
            horizon.input.setModeGameAndUI()
            horizon.showCursor()
        else:
            horizon.input.setModeGameOnly()
            horizon.hideCursor()

import horizon

class Impact(horizon.Behavior):
    # On a crate with a Particle System whose graph does not loop (sparks):
    # every hit fires a handful of sparks and gives the camera a short jolt.
    def on_collision_enter(self, other):
        made = horizon.particle.burst(self.entity_id, 24)
        if made > 0:
            # 5 cm, 0.5 degrees, 18 shakes per second, a quarter of a second.
            horizon.camera.playShake(0.05, 0.5, 18, 0.25)

import horizon

MUSIC = "Audio/theme.hasset"
VOLUME, FADE = 0.6, 2.0   # fade length in seconds

class MusicFade(horizon.Behavior):
    def on_start(self):
        self.music = horizon.audio.play(MUSIC, VOLUME, 1, True)
        self.left = 0.0

    # "EndLevel" is a button action.
    def on_input_pressed(self, name):
        if name == "EndLevel" and self.music != 0:
            self.left = FADE

    def on_update(self, dt):
        if self.left <= 0:
            return
        self.left -= dt
        if self.left <= 0:
            horizon.audio.stop(self.music)   # stop, not volume 0: frees the voice
            self.music = 0
        else:
            horizon.audio.setVolume(self.music, VOLUME * self.left / FADE)

import horizon

class SprintFov(horizon.Behavior):
    # "Sprint" is a button action. The kick widens the view for a moment and
    # falls back by itself; getFov keeps answering the authored value.
    def on_input_pressed(self, name):
        if name == "Sprint":
            horizon.camera.kickFov(8, 0.15, 0.6, 0.4)   # degrees, attack, hold, decay
            horizon.camera.setLagEnabled(True)           # the camera trails a little

    def on_input_released(self, name):
        if name == "Sprint":
            horizon.camera.setLagEnabled(False)
